package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		in   string
		want int
	}{
		{"hello", 2},
		{"AEIOU", 5},
		{"", 0},
		{"世界rhythm", 0},
		{"Go is Awesome", 6},
	}
	for _, c := range cases {
		if got := Solve(c.in); got != c.want {
			t.Errorf("Solve(%q)=%d want %d", c.in, got, c.want)
		}
	}
}

